import os,json,hashlib
from pathlib import Path
rows=[]
for name in ['/input','/helper','/helper/task03-attempt5-linux-public-transfer.py','/input/candidate-freeze-attempt5.json','/input/managed-fixture-copy-manifest.json']:
 p=Path(name);row={'path':name}
 try:
  s=p.stat();row.update(uid=s.st_uid,gid=s.st_gid,mode=s.st_mode,bytes=s.st_size)
  if p.is_dir():row['traversable']=os.access(p,os.R_OK|os.X_OK);row['members']=len(list(p.iterdir()))
  else:
   h=hashlib.sha256();count=0
   with p.open('rb') as f:
    while True:
     b=f.read(1048576)
     if not b:break
     h.update(b);count+=len(b)
   row.update(readable=True,EOF=True,sha256=h.hexdigest(),readBytes=count)
 except OSError as e:row.update(error=type(e).__name__,errno=e.errno)
 rows.append(row)
ok=all('error' not in x and x.get('traversable',x.get('readable',False)) for x in rows)
print(json.dumps({'status':'PASS' if ok else 'FAIL','uid':os.getuid(),'gid':os.getgid(),'rows':rows,'privateBytes':False,'candidateCopy':False,'services':False}))
raise SystemExit(0 if ok else 1)
